using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Hosting; using Microsoft.Extensions.Logging; using Microsoft.Extensions.Options; using UnicoreCRM.BuildingBlocks;
namespace UnicoreCRM.PlatformOperations.Outbox;
internal sealed class IntegrationEventRelayOptions{internal const string Section="IntegrationEvents:Relay";public int BatchSize{get;set;}=50;public int LeaseSeconds{get;set;}=120;public int IdleDelayMilliseconds{get;set;}=1000;}
internal sealed class IntegrationEventRelayWorker(IServiceScopeFactory scopes,IOptions<IntegrationEventRelayOptions> options,ILogger<IntegrationEventRelayWorker> log):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stop){var o=options.Value;while(!stop.IsCancellationRequested){var didWork=false;await using var scope=scopes.CreateAsyncScope();var journal=scope.ServiceProvider.GetRequiredService<IntegrationEventJournal>();foreach(var source in scope.ServiceProvider.GetServices<IIntegrationEventSource>()){IntegrationEventLease? lease=null;try{lease=await source.ClaimAsync(Math.Clamp(o.BatchSize,1,500),TimeSpan.FromSeconds(Math.Clamp(o.LeaseSeconds,30,1800)),stop);if(lease is null)continue;didWork=true;await journal.AdmitAsync(lease.Events,stop);await source.AcknowledgeAsync(lease.RelayAttemptId,lease.Events.Select(x=>x.EventId).ToArray(),stop);}catch(OperationCanceledException)when(stop.IsCancellationRequested){return;}catch(Exception ex){log.LogError(ex,"Integration Event relay failed for source {SourceOwner}",source.SourceOwner);if(lease is not null)try{await source.ReleaseAsync(lease.RelayAttemptId,lease.Events.Select(x=>x.EventId).ToArray(),"RELAY_FAILED",DateTimeOffset.UtcNow.AddMinutes(1),stop);}catch(Exception release){log.LogError(release,"Integration Event relay lease release failed for source {SourceOwner}",source.SourceOwner);}}}if(!didWork)await Task.Delay(Math.Clamp(o.IdleDelayMilliseconds,100,30000),stop);}}
}
